namespace Ipm.Domain.Common;

/// <summary>
/// Base class for every entity. Ids are UUIDv7 generated by the server (time-ordered, index friendly).
/// </summary>
public abstract class Entity
{
    private readonly List<IDomainEvent> _domainEvents = [];

    protected Entity(Guid id) => Id = id;

    /// <summary>Required by EF Core for materialization.</summary>
    protected Entity() { }

    public Guid Id { get; private init; } = Guid.CreateVersion7();

    /// <summary>
    /// Concurrency token (PostgreSQL <c>xmin</c>), changes on every save. Clients see it as the ETag;
    /// update handlers check the client's <c>If-Match</c> with <see cref="HasVersion"/> before changing anything.
    /// </summary>
    public uint Version { get; private set; }

    /// <summary>False means someone else saved this record after the client read it.</summary>
    public bool HasVersion(uint expected) => Version == expected;

    public IReadOnlyCollection<IDomainEvent> DomainEvents => _domainEvents.AsReadOnly();

    public void ClearDomainEvents() => _domainEvents.Clear();

    protected void RaiseDomainEvent(IDomainEvent domainEvent) => _domainEvents.Add(domainEvent);
}
